"""
app/services/projects.py – Persistence for projects generated by the Architect agent.
"""

import io
import re
import zipfile
from datetime import datetime, timezone
from posixpath import normpath

from bson import ObjectId
from pymongo import ReturnDocument

from app.core.database import GENERATED_PROJECTS, col

MAX_FILES = 200
MAX_FILE_BYTES = 200_000


def slugify(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")[:60] or "project"


def clean_path(path: str) -> str | None:
    """Normalise a generated file path; reject absolute paths and directory traversal."""
    path = path.strip().strip("`").replace("\\", "/").lstrip("/")
    if not path:
        return None
    path = normpath(path)
    if path.startswith("..") or path == "." or ":" in path.split("/")[0]:
        return None
    return path


def serialize_project(doc: dict, include_files: bool = False) -> dict:
    out = {
        "id": str(doc["_id"]),
        "name": doc["name"],
        "description": doc.get("description", ""),
        "tech_stack": doc.get("tech_stack", []),
        "file_count": len(doc.get("files", [])),
        "thread_id": doc.get("thread_id"),
        "created_at": doc["created_at"],
        "updated_at": doc["updated_at"],
    }
    if include_files:
        out["setup_instructions"] = doc.get("setup_instructions", "")
        out["files"] = sorted(doc.get("files", []), key=lambda f: f["path"])
    return out


async def save_project(
    user_id: str,
    thread_id: str | None,
    name: str,
    description: str,
    tech_stack: list[str],
    files: list[dict],
    setup_instructions: str,
) -> dict:
    """
    Create or update a project. Saving again with the same name in the same thread
    merges files (new paths are added, existing paths overwritten).
    """
    cleaned: dict[str, str] = {}
    for f in files[:MAX_FILES]:
        path = clean_path(f.get("path", ""))
        if path:
            cleaned[path] = (f.get("content") or "")[:MAX_FILE_BYTES]
    if not cleaned:
        raise ValueError("No valid files were provided")

    now = datetime.now(timezone.utc)
    key = {"user_id": user_id, "thread_id": thread_id, "slug": slugify(name)}
    existing = await col(GENERATED_PROJECTS).find_one(key, {"files": 1})
    merged = {f["path"]: f["content"] for f in (existing or {}).get("files", [])}
    merged.update(cleaned)

    return await col(GENERATED_PROJECTS).find_one_and_update(
        key,
        {
            "$set": {
                "name": name.strip()[:100],
                "description": description.strip(),
                "tech_stack": [t.strip() for t in tech_stack if t.strip()][:20],
                "setup_instructions": setup_instructions.strip(),
                "files": [{"path": p, "content": c} for p, c in sorted(merged.items())],
                "updated_at": now,
            },
            "$setOnInsert": {"created_at": now},
        },
        upsert=True,
        return_document=ReturnDocument.AFTER,
    )


async def list_projects(user_id: str) -> list[dict]:
    cursor = col(GENERATED_PROJECTS).find({"user_id": user_id}).sort("updated_at", -1)
    return [serialize_project(d) async for d in cursor]


async def get_project(user_id: str, project_id: str) -> dict | None:
    if not ObjectId.is_valid(project_id):
        return None
    return await col(GENERATED_PROJECTS).find_one({"_id": ObjectId(project_id), "user_id": user_id})


async def delete_project(user_id: str, project_id: str) -> bool:
    if not ObjectId.is_valid(project_id):
        return False
    res = await col(GENERATED_PROJECTS).delete_one({"_id": ObjectId(project_id), "user_id": user_id})
    return bool(res.deleted_count)


def build_zip(project: dict) -> tuple[bytes, str]:
    folder = project.get("slug") or slugify(project["name"])
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as zf:
        for f in project.get("files", []):
            zf.writestr(f"{folder}/{f['path']}", f["content"])
        if project.get("setup_instructions") and not any(
            f["path"].lower() == "setup.md" for f in project.get("files", [])
        ):
            zf.writestr(f"{folder}/SETUP.md", f"# Setup\n\n{project['setup_instructions']}\n")
    return buffer.getvalue(), f"{folder}.zip"
